import java.util.*;
import java.io.*;

public class Main {
    static long[] xorWorld(int[] types, long[] xs) {
        // Write your solution here
        return new long[0];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int q = (int) in.nval;
        int[] types = new int[q];
        long[] xs = new long[q];
        for (int i = 0; i < q; i++) {
            in.nextToken(); types[i] = (int) in.nval;
            in.nextToken(); xs[i] = (long) in.nval;
        }
        long[] res = xorWorld(types, xs);
        StringBuilder sb = new StringBuilder();
        for (long v : res) sb.append(v).append('\n');
        System.out.print(sb);
    }
}
